{
  "root": "mainStack",
  "state": {
    "scanState": "scanning"
  },
  "elements": {
    "mainStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg",
        "padding": 16
      },
      "children": [
        "title",
        "description",
        "divider1",
        "scannerSection",
        "divider2",
        "actionsSection"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Event Check-in Scanner",
        "variant": "h3"
      },
      "children": []
    },
    "description": {
      "type": "Text",
      "props": {
        "text": "This interface provides a streamlined process for validating attendee tickets via QR code for quick and efficient event entry. The screen transitions from a scanning view to a confirmation status upon a successful scan."
      },
      "children": []
    },
    "divider1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "scannerSection": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "scannerTitle",
        "viewContainer"
      ]
    },
    "scannerTitle": {
      "type": "Text",
      "props": {
        "text": "Scanner Interface & Confirmation",
        "variant": "h3"
      },
      "children": []
    },
    "viewContainer": {
      "type": "Stack",
      "props": {
        "direction": "vertical"
      },
      "children": [
        "scanningView",
        "successView"
      ]
    },
    "scanningView": {
      "type": "Card",
      "props": {},
      "children": [
        "scanningViewContent"
      ],
      "visible": {
        "$state": "/scanState",
        "eq": "scanning"
      },
      "on": {
        "press": {
          "action": "setState",
          "params": {
            "path": "/scanState",
            "value": "success"
          }
        }
      }
    },
    "scanningViewContent": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "align": "center",
        "padding": 16
      },
      "children": [
        "scanningViewTitle",
        "scanningIcon",
        "cameraViewText",
        "overlayText"
      ]
    },
    "scanningViewTitle": {
      "type": "Text",
      "props": {
        "text": "Scanning View"
      },
      "children": []
    },
    "scanningIcon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000043_01_1_qr-code-scan.svg"
      },
      "children": []
    },
    "cameraViewText": {
      "type": "Text",
      "props": {
        "text": "[Camera View Active]"
      },
      "children": []
    },
    "overlayText": {
      "type": "Text",
      "props": {
        "text": "Position the QR code inside the frame."
      },
      "children": []
    },
    "successView": {
      "type": "Card",
      "props": {},
      "children": [
        "successViewContent"
      ],
      "visible": {
        "$state": "/scanState",
        "eq": "success"
      }
    },
    "successViewContent": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "align": "center",
        "padding": 16
      },
      "children": [
        "successViewTitle",
        "successIcon",
        "successTitle",
        "attendeeInfo",
        "statusInfo"
      ]
    },
    "successViewTitle": {
      "type": "Text",
      "props": {
        "text": "Success View"
      },
      "children": []
    },
    "successIcon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000043_01_2_check-circle-fill.svg"
      },
      "children": []
    },
    "successTitle": {
      "type": "Text",
      "props": {
        "text": "Check-in Successful!",
        "variant": "h2"
      },
      "children": []
    },
    "attendeeInfo": {
      "type": "Text",
      "props": {
        "text": "Attendee: Jane Smith"
      },
      "children": []
    },
    "statusInfo": {
      "type": "Text",
      "props": {
        "text": "Status: Confirmed"
      },
      "children": []
    },
    "divider2": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "actionsSection": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "actionsTitle",
        "actionsStack"
      ]
    },
    "actionsTitle": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "actionsStack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md"
      },
      "children": [
        "resetButton"
      ]
    },
    "resetButton": {
      "type": "Button",
      "props": {
        "label": "Scan Next Ticket"
      },
      "children": [],
      "on": {
        "press": {
          "action": "setState",
          "params": {
            "path": "/scanState",
            "value": "scanning"
          }
        }
      }
    }
  }
}
